/**
 * Tabs 컴포넌트
 * 탭 전환 및 패널 표시 제어
 */
export function initTabs(root = document) {
  const tabGroups = root.querySelectorAll('[data-lg-tabs]');

  tabGroups.forEach((group) => {
    const tabs = group.querySelectorAll('.lg-tabs__tab');
    const panels = group.querySelectorAll('.lg-tabs__panel');

    tabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        const targetId = tab.dataset.lgTabTarget;

        tabs.forEach((t) => {
          t.classList.remove('lg-tabs__tab--active');
          t.setAttribute('aria-selected', 'false');
        });

        panels.forEach((panel) => {
          panel.classList.remove('lg-tabs__panel--active');
          panel.hidden = true;
        });

        tab.classList.add('lg-tabs__tab--active');
        tab.setAttribute('aria-selected', 'true');

        const targetPanel = group.querySelector(`#${targetId}`);
        if (targetPanel) {
          targetPanel.classList.add('lg-tabs__panel--active');
          targetPanel.hidden = false;
        }
      });
    });
  });
}

export default initTabs;
